const ResolveOperatorSession = `-- name: ResolveOperatorSession :one
SELECT s.session_id, s.operator_id, s.stage, s.expires_at, s.credential_id,
       a.subject_id, a.role, a.disabled_at,
       s.elevated_capability, s.elevated_until, s.elevation_reason
FROM operator_session s
JOIN operator_account a ON a.operator_id = s.operator_id
WHERE s.token_digest = $1
  AND s.ended_at IS NULL
  AND s.expires_at > $2
`

type ResolveOperatorSessionParams struct {
	TokenDigest []byte
	ExpiresAt   pgtype.Timestamptz
}

type ResolveOperatorSessionRow struct {
	SessionID          string
	OperatorID         string
	Stage              string
	ExpiresAt          pgtype.Timestamptz
	CredentialID       *string
	SubjectID          string
	Role               string
	DisabledAt         pgtype.Timestamptz
	ElevatedCapability *string
	ElevatedUntil      pgtype.Timestamptz
	ElevationReason    *string
}

// The authenticator's query, and it joins operator_account so a DISABLED
// operator's live session stops working the moment the disable projects —
// which is what operator.md §3 means by "offboarding is immediate".
//
// Expiry is compared in SQL rather than in Go so that "expired" is decided by
// the same clock that stored the row.
func (q *Queries) ResolveOperatorSession(ctx context.Context, arg ResolveOperatorSessionParams) (ResolveOperatorSessionRow, error) {
	row := q.db.QueryRow(ctx, ResolveOperatorSession, arg.TokenDigest, arg.ExpiresAt)
	var i ResolveOperatorSessionRow
	err := row.Scan(
		&i.SessionID,
		&i.OperatorID,
		&i.Stage,
		&i.ExpiresAt,
		&i.CredentialID,
		&i.SubjectID,
		&i.Role,
		&i.DisabledAt,
		&i.ElevatedCapability,
		&i.ElevatedUntil,
		&i.ElevationReason,
	)
	return i, err
}

