const UpsertCustomer = `-- name: UpsertCustomer :exec

INSERT INTO operator_customer_list (
    org_id, slug, org_name, lifecycle_state, owner_subject_id, org_created_at, updated_at
) VALUES ($1, $2, $3, $4, $5, $6, now())
ON CONFLICT (org_id) DO UPDATE SET
    slug             = EXCLUDED.slug,
    org_name         = EXCLUDED.org_name,
    lifecycle_state  = EXCLUDED.lifecycle_state,
    owner_subject_id = EXCLUDED.owner_subject_id,
    updated_at       = now()
`

type UpsertCustomerParams struct {
	OrgID          string
	Slug           string
	OrgName        string
	LifecycleState string
	OwnerSubjectID *string
	OrgCreatedAt   pgtype.Timestamptz
}

// ---------------------------------------------------------------------------
// The customer directory
// ---------------------------------------------------------------------------
func (q *Queries) UpsertCustomer(ctx context.Context, arg UpsertCustomerParams) error {
	_, err := q.db.Exec(ctx, UpsertCustomer,
		arg.OrgID,
		arg.Slug,
		arg.OrgName,
		arg.LifecycleState,
		arg.OwnerSubjectID,
		arg.OrgCreatedAt,
	)
	return err
}

const UpsertOperatorAccount = `-- name: UpsertOperatorAccount :exec
INSERT INTO operator_account (
    operator_id, subject_id, issuer, provider_subject, role, disabled_at, provisioned_at, updated_at
) VALUES ($1, $2, $3, $4, $5, $6, $7, now())
ON CONFLICT (operator_id) DO UPDATE SET
    role        = EXCLUDED.role,
    disabled_at = EXCLUDED.disabled_at,
    updated_at  = now()
`

type UpsertOperatorAccountParams struct {
	OperatorID      string
	SubjectID       string
	Issuer          string
	ProviderSubject string
	Role            string
	DisabledAt      pgtype.Timestamptz
	ProvisionedAt   pgtype.Timestamptz
}

// The projection's write. Idempotent on operator_id so a replay lands the same
// row rather than a duplicate.
func (q *Queries) UpsertOperatorAccount(ctx context.Context, arg UpsertOperatorAccountParams) error {
	_, err := q.db.Exec(ctx, UpsertOperatorAccount,
		arg.OperatorID,
		arg.SubjectID,
		arg.Issuer,
		arg.ProviderSubject,
		arg.Role,
		arg.DisabledAt,
		arg.ProvisionedAt,
	)
	return err
}
